"use client";

import "../../styles/teum-base.css";
import "../../styles/components/progress.css";
import { Progress as ProgressPrimitive } from "@base-ui/react/progress";
import type { CSSProperties } from "react";
import { cn } from "../../lib/cn";

export type ProgressProps = Omit<ProgressPrimitive.Root.Props, "children"> & {
  label?: string;
  "aria-label"?: string;
  showValue?: boolean;
  size?: "small" | "medium";
  className?: string;
};

export function Progress({ label, "aria-label": ariaLabel, showValue = true, size = "medium", className, value, min = 0, max = 100, style, ...props }: ProgressProps) {
  const range = max - min;
  const scale = typeof value === "number" && range > 0 ? Math.min(1, Math.max(0, (value - min) / range)) : 0.42;
  const progressStyle = { ...style, "--teum-progress-scale": scale } as CSSProperties;
  return (
    <ProgressPrimitive.Root className={cn("teum-progress", `teum-progress--${size}`, className)} value={value} min={min} max={max} aria-label={label ? undefined : ariaLabel ?? "Progress"} style={progressStyle} {...props}>
      {(label || showValue) && <div className="teum-progress__meta">{label ? <ProgressPrimitive.Label>{label}</ProgressPrimitive.Label> : <span />}{showValue && <ProgressPrimitive.Value />}</div>}
      <ProgressPrimitive.Track className="teum-progress__track">
        <ProgressPrimitive.Indicator className="teum-progress__indicator" />
      </ProgressPrimitive.Track>
    </ProgressPrimitive.Root>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-progress { display: grid; width: min(320px, 100%); gap: 7px; }

.teum-progress__meta { display: flex; align-items: center; justify-content: space-between; gap: 12px; color: var(--teum-ink-secondary); font-size: var(--teum-type-label); }

.teum-progress__meta > span:last-child { color: var(--teum-ink-tertiary); font-variant-numeric: tabular-nums; }

.teum-progress__track { position: relative; overflow: hidden; width: 100%; border-radius: 999px; background: var(--teum-gray-200); }

.teum-progress__indicator { width: 100%; height: 100%; border-radius: inherit; background: var(--teum-gray-900); transform: scaleX(var(--teum-progress-scale)); transform-origin: left center; transition: transform 220ms var(--teum-ease-out, ease-out); }

.teum-progress[data-indeterminate] .teum-progress__indicator { animation: teum-progress-indeterminate 1.15s var(--teum-ease-in-out, ease-in-out) infinite; }

@media (prefers-reduced-motion: reduce) {
.teum-progress[data-indeterminate] .teum-progress__indicator { animation-duration: 2.4s; }
}

@keyframes teum-progress-indeterminate { from { transform: translateX(-72%) scaleX(.42); } to { transform: translateX(116%) scaleX(.42); } }
}
